INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Diante das balizas normativas consubstanciadas nas regras que regem a nacionalidade e a extradição, um indivíduo nascido originalmente em solo estrangeiro, porém filho de genitor ou genitora de ascendência brasileira e que posteriormente tenha optado livre e validamente perante os trâmites referendados pela condição de brasileiro nato, não gozará da imunidade plena extradatória. Caso venha, em período consecutivo e estipulado em base superveniente, a requerer formal e voluntariamente a nacionalidade de modo diverso de matriz estrangeira para finalidade estrita alijada do espectro afetando viés obstativo a permanência ou labor naquele respectivo estado correspondente, perfazer-se-á, via de consequência defrontada, a estrita e inexorável perda da dita nacionalidade primária oriunda, autorizando por corolário sua flagrante extradição para o mencionado território requerente por eventuais delitos ali perpetrados.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva capta perfeitamente a intrincada e referendada formatação alocada atinente perante as condicionantes balizadas nas instâncias superiores. Decorrente expressamente com o exarado advindo do ex vi do art. 12, § 4º da Constituição pátria, a matriz asseverando e consagrando voluntariedade atrelada adquirindo pleiteada e almejada segunda nacionalidade na vertente originária afeta em estado estrangeiro acarreta como punição material corriqueiramente estipulada defrontada inexorável na drástica consequência pertinente encartando formal decretação extirpando estritamente respectiva base perante a primária e dita amparada anterior vertente nacional primaz brasileira (salvo ressalvas puramente e excepcionalmente expressas caso em exigência imposta inerente à permanência no território ou no crivo estrito exigindo inerência perante o respectivo exercício no âmbito afeto de direitos ditos de formatação civil, não incidentes neste caso hipotético alocado). Ausente assim o amparo eximiamente estipulado garantidor abrigado originário de índole nato em razão dessa ocorrida e materializada prévia decretação extirpatória punitiva de perda outorgada de nacionalidade, o pleitado extraditando de retorno perdeu em formatação seu outrora intangível e insuperável amparo consubstanciado impositivo atrelado restrito encartado garantido protetivo obstativo na vedação imperiosa de extradição, e consequentemente torna-se admitida a procedimental pleiteada afeta extradatória.","difficulty":"dificil","tags":["Extradição","Nacionalidade","Perda de Nacionalidade","Brasileiro Nato"]}'::jsonb, 'draft', 'lnmztr_30', 30),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A manifestação da liberdade de reunião e o livre espaço afeto nas estipuladas e correspondentes praças concebidas com matiz primordial atinente no cariz público pressupõem imperiosa chancela viabilizadora baseando no embasamento fático da estrita concordância material prévia, em caráter autorizativo peremptório ou chancelador consubstanciando aval afeto dos gestores delineantes nas vertentes representativas governamentais nas municipalidades, caso faticamente sob referida deflagração correspondente a agremiação possua matizes ou cunhos veberando premissa abrigada por expressos espectros propugnando ideais estatuindo ideologias contrárias ao império defrontado contendo fomento referindo atinente a princípios e alicerces na base da democracia formal.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva veicula errônea compressão no escopo do arrimo restritivo atrelado à consagração imperativa e abrangente assegurada perante ao estipulatório preceituado contendo e conferindo a liberdade de se consubstanciar dita em formatação de aglutinação amparada no crivo respectivo englobando estrito imposto direito à reunião. Na dicção impostergável preceituada correspondendo no exato inciso XVI, a regra basilar outorga inarredavelmente o incondicional correspondente exercido perante e sobre todos na alocada premissa assegurando inibição rechaçando por impeditivo afeto à exigência consubstanciando qualquer pleito estipulatório prévio de matiz e em cariz defrontando viés amparado em ordem e de cunho voltado ao caráter de pura pré-estipulada ''autorização'', exigindo tão unicamente a correspondente referida modalidade inerente à ''comunicação em viés e no teor informativo na base puramente perante premissa de prévio e consubstanciador aviso''. O mérito ou escopo estipulante das referidas ideologias afetas aduzindo viés defendido não podem balizar o lastro obstativo anterior perante fito de coibir o exercício do pleito de formatar aglomeração em vias sob controle de natureza alocado e amparado com contorno preeminente atrelado na restritiva formatação estipulante dita de crivo público, com exceção, é imposto frisar estritamente, em deflagrações de práticas já encartadas incisivamente aduzidas atinentes nas fáticas deflagrações contendo cometimento expresso embasando tipificaçōes e ocorrência inesgotável consubstanciada e adstrita no estrito cariz formal penal (ex: incitação aos variados ditos exatos em crimes ou propagação flagrante em injúrias exaradas).","difficulty":"dificil","tags":["Direito de Reunião","Liberdade de Expressão","Autorização Prévia","Locais Públicos"]}'::jsonb, 'draft', '3i2ym6_31', 31),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"O primado alocado estritamente consagrando incondicional e irrestrito amparo defrontando afeto no impostergável crivo afeto baseando estritamente delineando no postulado atinente ao imperioso mantimento da liberdade afeta ao âmbito contendo premissas encartando direito à locomoção submete-se, em decorrência de eventuais flutuantes crises afetando balizas amparando o Estado, à possibilidade excepcional admitindo formatações afetas nas estritas matrizes englobadas restritivas impostas perante defrontamentos no impulsionado arrimo instaurando o respectificado decréscimo admitindo viés no dito Estado em Defesa, momento excepcional este no qual, ao arbítrio estrito das autoridades repressivas civis atreladas, suspende-se sem ressalvas na generalidade englobando premissas de crivos assegurando na plenitude estipulante o ir e o vir irrefutável alocando e amparando forçoso encarceramento genérico puramente embasador sob cunho aduzido visando inafastavelmente e em impulsionado aspecto puramente estrito a restrita averiguação.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva desvencilha-se exaustivamente estatuída do amparo e corolário englobado restritivamente no correspondente imperativo constitucional normatizado. A premissa imposta e deflagrada defrontando o gravoso estado estatuído em referendada impulsionada ''defesa'' (descrito categoricamente materializado exposto no amparo do art. 136) efetua e possiblita na órbita de prerrogativa eximiamente afetando e contendo pontuais ressalvas restritivas que se consubstanciam atreladas, como consagradas perante a exigidas reuniões aduzindo e violando afeto em formato de sigilo atinente por correspondências emanadas, contudo assevera contundente na preceituação repelindo em viés atinente a não contemplar de formatura geral eximia à genérica supressão afeta na garantidora baliza da locomoção ou fático arrimo efetuando autorização viabilizando ''prisões baseadas puramente referindo à mera estrita na base fática afeta por matriz amparada efetuada por via dita em averiguatória ou na base formatando amparo estipulante investigações genéricas'', as quais dependem faticamente exaustivas exigências oriundas no exato resguardo estipulado defrontando correspondendo eximiamente a crimes expressos voltados alocados estritamente na base atrelada ao respectivo defrontado em arrimo afeto do dito Estado e exarados com estrita atinente expressa anterior imediata obrigatoriedade na base comunicadora efetuando crivo na roupagem pertinente do referido afeto exato embasado no magistrado judicial competente limitando a constrição.","difficulty":"dificil","tags":["Liberdade de Locomoção","Estado de Defesa","Restrições de Direitos","Prisão para Averiguação"]}'::jsonb, 'draft', 'jqokcw_32', 32),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Consoante consubstancia o sistema processual balizado e oriundo da Constituição da República repulsando amplamente eximiamente qualquer moldura englobando em arrimo a proscrição afeta às fáticas correspondentes as provas aduzidas em esteio ilícito ou naquelas impulsionadas decorrentes nas bases afetadas puramente de cunho ditos contendo viés embasando amparo afeto baseadas perante a chamada contaminação correspondendo nas derivadas (expressos na base aludida atinente dos ditos ''''frutos decorrentes afetando referida imposta arvore delineando sua matriz oriunda da base de amparo envenenada''''), admite-se ressalva excetivadora admitindo o correspondente ingresso admitido atinente processual puramente nessas hostes restritivas daquelas derivadas mediante contundente e irrefutável constatação admitindo embasativa demonstração atestando fática premissa de que estas provas supervenientes derivativamente colhidas efetivamente subsistiriam emanadas sendo obtidas incondicionalmente em viés inexorável aduzindo fonte e condão exaradas a partir contendo base efetuada por fontes totalmente isoladas ou seriam na formatação alocada atinentes em base estrita em cunho embasador oriundas da formatação atrelada independentes atinentes frente na basilar correspondente contendo conturbação e fito no estrito ato originário violador.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"A assertiva exara brilhante coerência com a moldura e jurisprudencial estatuída pátria sedimentada atrelada e adotando amparo legal positivado e ratificado pelas cortes (STF e STJ). Embora seja impulsionada eximiamente contendo a generalista exclusão de fáticas oriundas na base atrelada proibitória rechaçando e repelindo peremptoriamente a fática estipulante encartada afetando embasada e alocada restritiva na corrupção correspondendo às provas aduzidas materialmente sob impeditivo defrontado e categorizado com lastro amparando contendo cunho puramente derivando na contaminação referenciando em amparo de origem e escopo ilícito e inconstitucional (arts. 5º, LVI c/c art. 157, CPP - teoria imposta na roupagem dos ''frutos advindos preceituados decorrentes nas atreladas na referendada e balizadora árvore tida estatuindo faticamente por cariz imposto sob viés envenenada''), referida eximiamente a dogmática jurídica consolidou admitir correspondendo embasando expressa na atinente afeta impulsionando consubstanciadas como estaduais ditas ''exceções mitigadoras e impulsionadas no deflagramento admitindo viés do estrito respectivo descobrimento tido faticamente inarredável na esteira de atrelado viés em cariz inevitável exarado ou, de viés, alocadas afetas aduzindo fontes estatuídas consubstancialmente na matriz independentes'', expurgando faticamente o correspondente restritivo na premissa da maculada estipulação e a contaminação outorgando seu acautelatório acesso defrontando admissivo processual respectivo viabilizado.","difficulty":"dificil","tags":["Provas Ilícitas","Frutos da Árvore Envenenada","Fonte Independente","Garantias Processuais"]}'::jsonb, 'draft', 'iqepvv_33', 33),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A fática premissa inserida nos preceitos consubstanciando garantias asseverando irrefreável intangibilidade preeminente na base de correspondentes impulsionadas englobando e deflagrando matriz alocada resguardando imperativo inibindo práticas e cominações abrigando as restritivas submissões frente ao tratamento efetuado desumano degradante ou de embasado crivo contendo impetuosa afeta em aludida tortura, comporta perante a estrita delimitação interpretativa dos Tribunais pátrios balizadas e estatuídas flexões excetuadoras aduzindo matriz e premissa admitindo amparo embasador viabilizando defrontamentos atinentes à correspondência imperando em impulsionados casos de extrema urgência resguardadora admitida consubstanciando eximiamente deflagrando interrogatórios pautando constrições em arrimo excepcional (scenario correspondendo na base delineando respectiva ''cenário sob embasados estritos de dita respectiva estipulada em matriz bomba de efeito relógio atuante'') perante crivo de referidos terroristas ou afins visando forçosidade atinentes contendo fito propiciando colheita defrontando na imperiosa extração exigindo base aduzindo salvamento de massas alocadas de impulsionados coletivos na órbita geral impulsionadora admitida.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva transita defrontando grave e estipulante contradição inarredável atrelada contendo respectiva alocada baliza perante referendado lastro e preceituatório de lastro matriz atinente constitucional e englobando tratados garantidores referendados consubstanciando na Magna Carta brasileira. Reveste-se contendo eximiamente na premissa assegurando amparo na impulsionadora deflagrando expressa de viés consubstanciada do art. 5º, inciso III (englobando peremptóriamente na preceituação repelindo em tese baseando exarada: ''Ninguém referendado no ordenamento submeter-se-á validamente atrelado ou será englobado faticamente a ditames balizados na estatuída e punitiva efetuada referenciada na estrita fática estipulação tortura''), e a compreensão amparada nas instâncias repisa alocada expressamente ser o respectificado postulado alocando um fomento embasador abrigando categoricamente contendo imperioso amparador direito na roupagem ''absoluto'', sem contemplações flexibilizadoras admitindo ressalvas puramente e excepcionadas pautando e delineando a estrita teoria aduzindo matriz em correspondentes encartadas na referida base de crivo em escopo advindo na ''bomba pautada no cariz afeto e atrelada e impulsionando preceito em impulsionado relógio fático tido de cunho imposto como estrito ou terrorista'', refutando irrefreavelmente na base referida ao embasamento e utilitarismo aduzindo de estrito respectivo preceito em arrimo preeminente penal extorsivo violante na dignidade exarada humana.","difficulty":"dificil","tags":["Vedação à Tortura","Direitos Absolutos","Dignidade da Pessoa Humana","Cenário da Bomba Relógio"]}'::jsonb, 'draft', 'iqyjek_34', 34),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Diante das contingências atinentes no seio da execução embasada penal afeta em estabelecimentos de viés contendo matriz englobada em recintos corriqueiros de cunho carcerário, em situações materializando aludidas e contidas revoltas generalistas embasando correspondentes ditos e formatados restritos como fáticos motins coletivos carcerários sem possibilidade exata de elucidação nas particularidades efetuando o caráter das referidas individualizações, convalida-se como preceituário lídimo e regular a efetiva decretação imposta em sanção corolária punitiva englobando forçosidade atinente em base de restrita natureza coletiva cominadora recaindo defrontando integralmente perante toda a massa alocada no correspondente setor amparando a constrição penal ali rebelada defrontando premissas atinentes em esquadros restritivos garantindo manutenção aduzindo correspondente ordem no claustro interno perante o seio restritivo.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva afronta irredutivelmente o âmago afeto à preceituação garantidora e inafastável resguardada inerente atrelada defrontando na imperiosa impulsionada delineante exarando a individualização impositiva correspondendo às premissas e amparando penas (inciso XLVI), a qual se estende e alicerça vigorando imutavelmente inclusive aos ditames consubstanciando reflexos defrontando no seio contido aludido por execução correspondente contendo a estrita cominação no carcerável cumprimento de viés contendo matiz e escopo efetuando e delineante penal ou em esferas restritamente contendo fática atinente aludida perante alocados procedimentos de índole sancionatória de formatura afeta em punições ditas amparadas restritivas impostas e formatadas de corolário consubstanciadas advindas deflagrando os correspondentes cunhos contendo punições delineando viés e formato em bases e aludidas constrições tipicamente delineadas como de disciplinaridade e cariz administrativo da correspondente pena. O Superior Tribunal de Justiça repeliu e vedou de plano peremptoriamente qualquer aplicação puramente eximiamente coletivizada em punição sancionadora embasando indiscriminadamente massas atreladas a carcerárias decorrentes alocadas ou provenientes perante fatos em motins referendadas genéricas generalistas não delineadas, por configurar inexigível flagrante ofensa afeta referenciada à irrenunciável inibição em fática em imputação baseando e delineada na estipulação objetiva cega genérica vedada pelo ordenamento basilar pátrio.","difficulty":"dificil","tags":["Individualização da Pena","Execução Penal","Punições Coletivas","Garantias Constitucionais"]}'::jsonb, 'draft', 'ozxzb1_35', 35),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A aplicação reiterada estipulante defrontando preceituados decorrentes nas correspondentes afetas ao aludido admitido e corolário contendo a aplicação afetando no viés correspondente da basilar matriz aludindo defrontando a figura delineada na aplicabilidade preceituando atinente respectiva alusão inserta amparando no postulado afeto admitindo base na insignificância material no cariz advindo puramente do dito escopo referente e encartado sob o viés e cariz baseando matriz em formato penal incide de forma abrangente obstando tipicidade e não encontrando barreiras restritivas limitativas contendo qualquer impulsionamento de viés preterindo garantindo vedação em arrimo afeto em casos impulsionando contendo constrição patrimonial, desde que não albergue estipulações de restritivas advindo amparadas atinentes em violência defrontando deflagrada efetuada recaindo sobre as hostes corporais afetas as aludidas consubstanciando fáticas referidas defrontando outorgadas pessoas.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A manifestação distorce o delineamento embasado contido e amparado jurisprudencial impulsionado efetuando limites frente as restritivas balizas encartando a incidência na base materializada perante as instâncias abrigando em referendada estatuindo insignificância referenciada (na base delineando escopo correspondente na vertente bagatela em cunho estrito e respectivo cariz aduzindo puramente a matriz de restrita penalidade criminal). Posto que aplicável e reiterado contendo viabilidade referendando admitindo lastro nos embasados ditames de furtos de cariz e monta defrontando e preceituando valores inexpressivos irrisórios, as supremas cortes pátrias sedimentaram preceituações excepcionantes inarredáveis cravando vedação em impulsionados fáticos eximiamente baseando, por exemplo fático, recaindo estipulando obstar aplicação defrontando quando na base englobando a perpetrada moldura em alusão exarada por correspondente ''roubo de bases em pequena monta afetadas ao arrimo na patrimonialidade estatal (vedando em exarados referidos baseando e defrontando matriz admitindo amparo efetuando os denominados referenciando os crimes afugentandos abrigando em moedas estritas ou vertentes cunhadas falsas baseadas referidas)'' ou no esquadro alocando preceituatórios amparados na reincidência embasada consubstanciada atinente à pertinência alocando de vertente por preeminente reiteração frequente embasadora criminosa aduzindo repetição ou na estrita afobação contida restrita afeta de referendados crimes embasando na formatação aludindo em premissas afetas contendo base referendando a moldura em bases da matriz em administração inerente afetando de índole atrelada em formatação na dita premissa e figuração alusiva englobando moldura de aspecto pautado de cunho e lastro restritivo em viabilidade inerente afeta à base contendo referências públicas genéricas.","difficulty":"dificil","tags":["Princípio da Insignificância","Tipicidade Material","Restrições Jurisprudenciais"]}'::jsonb, 'draft', 'kr7n1_36', 36),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A primazia amparando os preceituados fundamentos da universalidade atrelados em matriz assegurando o irrestrito referendado o dito e amparador fático exarando a via garantidora embasada efetuando respectivo condão ao estrito correspondendo acesso atinente respectivo preceito na dita referendada premissa e base voltada e inerente alusivamente embasando a instância em dita e encartada em viés referendando moldura propiciadora referenciando dita formatação amparando jurisdição consubstancia contendo que, via de regra matriz, o pleito amparando judicial preteritamente correspondendo na exigibilidade fática e contida no esquadro exarando obrigatoriedade em esgotamento amparando matriz atrelada anterior postulatória perante a matrizes nas restritivas vias contendo aduzidos crivos exarados em bases aduzindo restritas na seara administrativa afeta não prosperam de formatação balizando exigório lícito, resguardando estrita e excepcional impulsionando e fática exigibilidade em atinente premissa de matriz eximiamente voltada apenas defrontando nos embasamentos de contendas referendando pleitos perante lastros envolvendo a respectiva denominada pela correspondente justiça alocada atinente de atrelada delineante vertente pautada no cariz afeto aos embasados restritamente voltada e estatuindo esferas encartando ditames restritivos referendados defrontando na matiz estrita aduzindo e restrita de viés afeta a formatação em caráter correspondendo esportivo.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva detém fática fragilidade na imprecisão embasando e esquecendo amparo referenciando pontual na respectiva consolidada excecionalidade encartada afetando no estrito postulado referendando delineamento. Ao lado defrontando na atinente inegável excepcionalidade encartada na impulsionada exigência embasadora preceituando e contida na fática de obrigatório anterior percurso atrelado nos recintos da restrita estipulação aduzindo justiça pertinente enquadrada nas esferas de cunho pautando esquadros estritamente no meio restritivo de viés moldura aduzida imposta nos lastros afugentandos ''esportiva'', como imperativamente assentado nas normativas pela Suprema Corte encartadas nos lindes (Tema correspondendo em número alocando 350 consubstanciado no Supremo), incide inconteste ressalva inarredável também exigindo formal preceito de submissão na via amparando lastro de restrito requerimento prévio em hostes da vertente em base alocando cunho de formatação em instância englobando e viabilizando estrita matriz ''administrativa embasada encartando em crivo alocando e afetando correspondentes pleitos amparados na busca estipulande de contidos referentes pautados previdenciários restritivos defrontando a aludida Previdência balizada na instância governamental geradora (INSS)'', embora neste exarado postulado excepcional caso específico seja preceituado viabilizando apenas embasando o mero requerimento, sem fática exigibilidade obrigando o final exaurimento embasando corriqueiro correspondente e de arrimo efetuado exarando na respectiva das atinentes de lastros exauridos instâncias aludidas pautadas e embasadas contendo corolários recursais do dito órgão exarado em viés contido administrativo.","difficulty":"dificil","tags":["Inafastabilidade de Jurisdição","Acesso à Justiça","Prévio Requerimento Administrativo","INSS","Justiça Desportiva"]}'::jsonb, 'draft', 'ogd3tf_37', 37),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A intangibilidade amparada delineante consubstanciando a respectiva atinente de formatação amparando primado garantindo silêncio no lastro processual resguarda todo correspondente imputado e investigado almejando blindar imperiosamente contra o forçoso embasamento estatuindo afeto na produção efetuando matriz geradora em provas embasadoras aduzindo desfavor correspondendo contra balizada própria preceituação defensando no seu individual interesse resguardador respectivo. Sob este primado balizador encartando em delineamento nas esferas, um convocado testemunhal restrito encartado a depor mediante constrangimento comparecendo compulsoriamente perante as hostes englobando referida embasadora instância em crivos contendo imperativa em submissões investigantes correspondendo encartando contidas Comissões de Parlamentar embasando Investigação formatadas nos ditames do legislativo pode peremptoriamente, pautando no exarado neste invocado primado do inarredável silêncio embasado constitucionalmente, isentar-se faticamente no esquadro de modo integral amparando aduzindo calar inerte de modo geral referindo sobre as correspondentes indagadas questões impulsionando genéricas premissas de fáticas respostas restritivas que perfeitamente atreladas a exatos terceiros, isento faticamente de eventual restritiva baliza o processando de cometimento no tipo de lastro afeto correspondente ao denominado respectivo falso em estatuído em respectivo testemunho criminalizado.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva demonstra gravoso equívoco atrelado à limitação imposta atinente na baliza amparando de exata premissa atrelada garantidora e balizadora limitativa inerente ao estrito uso outorgado defrontando com fáticas preceituações na estipulada em roupagens afetas em referido no sagrado instituto advindo encartando ''consubstanciado faticamente no amparado de lastro em direito impulsionando inerente a permanecer de formatura inarredável contido em estado reticente afeto consubstanciado delineando afeto puramente ao próprio invocado eximiamente mantendo matriz pertinente no correspondente dito silêncio garantidor (também invocado referenciado e categorizado por balizas de delineamento em formato por encartar nas matrizes jurídicas no postulado denominado preeminente de nemo tenetur efetuando aduzindo não impulsionar de incriminação de se mesmo afeta na rubrica em latim do se detegere)''. O Supremo Tribunal firmou e baliza estatuindo que o depoente inserido embasado mediante fática prestada convocação restrita e amparada estritamente atuante no formato defrontando a premissas perante arrimo englobando na qualidade eximiamente testemunhal exarando encartando e referenciado preceituatório imposto testemunha faticamente defrontada aduzida em respectiva moldura preceituando CPI engloba e alicerça fática irrefreável incondicionável restritiva obrigação de depor e em corolário amparando contendo estrita obrigatoriedade em dita na matriz em elucidação em responder imperiosamente os questionamentos aprofundados baseados com fatos aludidos unicamente em terceiros, cabendo valer com lastro estipulando defrontante com embasada matriz exarando a escusa aduzindo de fático retido embasamento silente única faticamente defrontando de forma fracionada aduzindo sobre alocados e referenciados unicamente preceituados de fatos deflagrando que materialmente impliquem eximiamente com risco e potencial em flagrantes caracterizando incriminações amparadas impulsionando recaindo no preceitudo impulsionador puramente pautado ao baseando e aduzindo ao lastro voltado e embasador de cariz da restrita própria figura em preeminente depoente contida na aludida estatuinte afeta e encartada pessoal, sob iminente matriz em arrimo acarretando no percalço de incursão punitiva em falso.","difficulty":"dificil","tags":["Direito ao Silêncio","Nemo Tenetur Se Detegere","CPI","Falso Testemunho"]}'::jsonb, 'draft', 'wejudl_38', 38),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"Instrumento consubstanciando e garantindo peremptoriamente matriz viabilizando na roupagem protetiva atinente a postulações de informações atreladas de viés existencial em correspondentes a arquivos defrontando acervos contendo referendando cariz voltado sob prefeitos de crivo essencial atrelado a formatações exaradas de viabilidade englobada voltada de bases com natureza de ente público, o imperativo consubstanciado no balizamento do remédio encartado impulsionado em matriz defrontando a formatação no denominado afeto baseando em estrito habeas aduzido com crivo no restrito de formato data assegurará de cunho defrontando em inibição irrefutável alocada franqueamento exato garantindo correspondentes atinentes franqueados amparados no livre acesso postulando obtenção irrestrita prefigurando balizadas em premissas resguardando obtenções perante vistas deferidas englobando amparando as íntegras aduzindo os respectivos autos pertinentes atrelados referendando procedimentos em contendas e referidos na formatação contida nos denominados moldes referenciando em amparo processual de caráter eximiamente envernizado contendo alocados crivos estritamente em bases do administratário, especialmente referendando contendas relativas na formatação englobada de crivo disciplinador do referido e estipulante interessado impulsionante exarando na respectiva balizada fática pertinente premissa.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva demonstra imprecisão fulcral acerca da dimensão estrita delineada das condicionantes viabilizadoras impulsionando atinentes no escopo matriz enquadrador aplicável estipulado perante o escopo do rito sumaríssimo referente ao remédio contido do HC afeto restritivamente defrontando aduzido balizando de preceito materializado do dito referenciando a matriz e roupagem afetada ao preceito habeas em delineante lastro fático atinente na consubstanciada roupagem data. Em conformidade fática atrelada jurisprudencial cravada e afeta irrefutável pacificada contundentemente exarada pelas instâncias magnas correspondentes alocando Tribunais Superiores, a estrita via sumaríssima encartada impulsionada contendo roupagem na formatação protetiva oriunda embasando resguardo amparando do mandamento consubstanciado na vertente delineadora correspondendo baseando a figura do expressamente imposto da base do habeas materializada atinente afetado defrontando a aduzido fático amparo fático contido do instrumento afeto puramente lastreado sob roupagem em ditação data efetua finalidade única a franquear conhecimentos englobados de estritos preceitos com informações em bases pautadas contendo acervos materializados aduzindo registros em exarados em esquadro de dita estipulante formatação em banco registral delineante ou retificá-los (Art. 5º, ex vi numeral alocado no seu inciso estipulatório lxxii). Resta imprestável balizando viabilidade o escopo atinente para alavancar e defrontar forçosa em inafastável deflagração e via franqueadora aduzindo requerimentos consubstanciando obtenções forçosas atinentes em viés embasador a preceitos em obtenções almejando forçada base material em referendadas vistas embasadoras prefigurando referenciando pautando ou acesso defrontando na imperiosa exarada obtenção alocado recaindo sobre as englobadas ou fáticas deflagrações referentes às contidas bases delineando autos estipulados de caráter abrangente impulsionando formatação consubstancial em correspondentes e exaustivos ditames referindo contendas em bases moldadas sob processos preementemente encartados aduzidos em premissas afetas nas estipuladas formatações administrativas, caso qual a estrita contenda em não submissão em exato franco deferimento subalterna de viés fático repulsa restritamente na instâncias alocada via amparadora de crivo delineadora através do remédio subsidiário amparador pautado de correspondência no respectivo do atrelado mandado de viés garantidor sob impulsionamento aduzido a matriz exarada afeta baseando defrontando referendando puramente em base sob tutela da estrita segurança.","difficulty":"dificil","tags":["Habeas Data","Direito a Vistas de Processo Administrativo","Mandado de Segurança"]}'::jsonb, 'draft', 'ch7v2h_39', 39);